import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"02 - Backend Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/02-backend-architecture.md","filePath":"developers/design-documentation/02-backend-architecture.md"}'),o={name:"developers/design-documentation/02-backend-architecture.md"};function n(i,e,d,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="_02-backend-architecture" tabindex="-1">02 - Backend Architecture <a class="header-anchor" href="#_02-backend-architecture" aria-label="Permalink to &quot;02 - Backend Architecture&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Tradeboard uses Flask 3.1 with Flask-RESTX, Flask-SocketIO, Flask-Limiter, Flask-WTF CSRF, SQLAlchemy, APScheduler, DuckDB, ZeroMQ, and a separate asyncio WebSocket proxy. Python <code>&gt;=3.12</code> is required.</p><p>The backend is a single-user application. Production runs Gunicorn with a single eventlet worker (<code>start.sh</code> passes <code>--worker-class eventlet --workers 1</code>), and the market-data proxy runs outside it in its own process. Process-local components such as caches and the EventBus are therefore per process, not shared. Cross-process market-data and selected cache invalidation paths use ZeroMQ.</p><h2 id="request-surfaces" tabindex="-1">Request Surfaces <a class="header-anchor" href="#request-surfaces" aria-label="Permalink to &quot;Request Surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Registration</th><th>Authentication</th></tr></thead><tbody><tr><td>REST v1</td><td><code>restx_api/__init__.py</code>, prefix <code>/api/v1</code></td><td>Tradeboard API key; CSRF exempt</td></tr><tr><td>Session APIs and webhooks</td><td><code>blueprints/*.py</code></td><td>Flask session, webhook secret, or explicit exemption</td></tr><tr><td>React bundle</td><td><code>blueprints/react_app.py</code></td><td>Route-specific frontend/auth gates</td></tr><tr><td>Socket.IO</td><td><code>extensions.py</code> and subscribers</td><td>Flask/Socket.IO lifecycle</td></tr><tr><td>Market-data WebSocket</td><td><code>websocket_proxy/server.py</code>, port 8765</td><td>Authenticate action with API key</td></tr><tr><td>Remote MCP</td><td>Conditional in <code>app.py</code></td><td>OAuth 2.1 bearer tokens</td></tr></tbody></table><p>Flask-RESTX&#39;s Swagger UI is intentionally disabled through <code>doc=False</code>. The <a href="./../../api-documentation/v1/README">API documentation</a> is the maintained external contract.</p><h2 id="application-factory" tabindex="-1">Application Factory <a class="header-anchor" href="#application-factory" aria-label="Permalink to &quot;Application Factory&quot;">​</a></h2><p><code>create_app()</code> initializes Flask, Socket.IO, EventBus subscribers, CSRF, limiter, CORS, CSP, security middleware, traffic/latency/health hooks, React routes, RESTX, feature blueprints, the broker keepalive service, and the real-time order-update adapters. The scoped-session teardown handler is registered at module scope after the factory returns. Remote MCP blueprints are imported and registered only when <code>MCP_HTTP_ENABLED=True</code> passes startup safety checks.</p><h2 id="service-flow" tabindex="-1">Service Flow <a class="header-anchor" href="#service-flow" aria-label="Permalink to &quot;Service Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP resource or blueprint</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>schema/session validation</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>service orchestration</span></span>
<span class="line"><span>   |          |          |</span></span>
<span class="line"><span>   v          v          v</span></span>
<span class="line"><span>live broker  sandbox   Action Center</span></span>
<span class="line"><span>module       manager   pending execution</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>typed EventBus events -&gt; log / Socket.IO / Telegram / WhatsApp / proxy-relay / strategy-book subscribers</span></span></code></pre></div><p>Order services strip sensitive fields before logging events. Analyzer mode routes supported operations to sandbox managers. Semi-auto mode queues eligible operations in Action Center and blocks specific destructive calls according to each service&#39;s policy.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>SQLAlchemy modules use scoped sessions and <code>NullPool</code> for SQLite. <code>utils/db_sessions.py</code> owns the registry of every scoped session; <code>app.py</code>&#39;s <code>teardown_appcontext</code> handler calls <code>remove_all_scoped_sessions()</code> after each request, and background threads that run without an app context call the same function themselves. Historify owns a separate DuckDB file and its own connection discipline. See <a href="./18-database-structure">18 Database Structure</a>.</p><h2 id="background-components" tabindex="-1">Background Components <a class="header-anchor" href="#background-components" aria-label="Permalink to &quot;Background Components&quot;">​</a></h2><ul><li>APScheduler jobs for Flow, Python strategies, Historify, and maintenance paths.</li><li>Sandbox execution, square-off, and settlement workers.</li><li>Broker keepalive service.</li><li>Real-time order-update adapters that ingest broker order pushes or postbacks and republish them as <code>order.update</code> events.</li><li>Scalping risk monitor that subscribes to live ticks and survives browser navigation.</li><li>Telegram/WhatsApp service startup when configured.</li><li>WebSocket proxy process under eventlet/gunicorn, or OS thread in direct development startup.</li><li>Health metrics and database initialization work.</li></ul><h2 id="security-boundaries" tabindex="-1">Security Boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security Boundaries&quot;">​</a></h2><ul><li><code>APP_KEY</code> and <code>API_KEY_PEPPER</code> are startup requirements.</li><li>Broker tokens and retrievable API keys are Fernet-encrypted; API-key verification uses Argon2 plus a pepper.</li><li>Session routes retain CSRF except explicit broker-callback, webhook, postback, and health exemptions. <code>auth.logout</code> is deliberately not exempt.</li><li><code>/api/v1</code> is CSRF-exempt because it uses API-key authentication.</li><li>CORS, CSP, proxy-header trust, IP bans, cookie security, and session expiry are environment controlled.</li><li>Debug mode on a non-loopback host is refused unless explicitly overridden; Remote MCP refuses debug mode.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>app.py</code></td><td>Factory, registration, setup, startup</td></tr><tr><td><code>restx_api/__init__.py</code></td><td>Public v1 namespace registry</td></tr><tr><td><code>blueprints/react_app.py</code></td><td>SPA serving and route aliases</td></tr><tr><td><code>services/order_router_service.py</code></td><td>Auto/semi-auto routing</td></tr><tr><td><code>utils/plugin_loader.py</code></td><td>Broker discovery and lazy auth imports</td></tr><tr><td><code>database/engine_factory.py</code></td><td>SQLite engine policy</td></tr><tr><td><code>utils/db_sessions.py</code></td><td>Scoped-session registry and release</td></tr><tr><td><code>utils/event_bus.py</code></td><td>Per-process async event dispatch</td></tr><tr><td><code>websocket_proxy/app_integration.py</code></td><td>Proxy lifecycle selection</td></tr></tbody></table>`,20)])])}const b=t(o,[["render",n]]);export{h as __pageData,b as default};
